    {
      "name": "complexity_C",
      "definition": "Expectation value of the complexity operator, defined as C = -lim_{alpha->0} partial_alpha <e^{-alpha C}>_reg.",
      "unit": "dimensionless",
      "statistic": "Ensemble-averaged expectation value in the TFD state.",
      "uncertainty": "source_unspecified",
      "resolution": null,
      "anchors": [
        {
          "line_start": 286,
          "line_end": 288,
          "support": "C := -lim_{alpha->0} partial_alpha (<e^{-alpha C}>_reg)."
