  ],
  "claims": [
    {
      "claim_id": "complexity_time_evolution",
      "statement": "The expectation value of quantum complexity in the GUE example evolves as C(t) = M t (1 - t/T_H + t^2/(3 T_H^2)) for t < T_H, and saturates to C(t) = (1/3) M T_H for t >= T_H, up to an undetermined additive constant.",
      "quantitative_form": "C(t) = M * t * (1 - t/T_H + t^2/(3*T_H^2)) for t < T_H; C(t) = (1/3) * M * T_H for t >= T_H",
      "oracle_outputs": {
        "complexity_C": {
          "op": "add",
          "args": [
            {
              "op": "multiply",
              "args": [
                {"param": "M_linear_growth_rate"},
                {"var": "time_t"},
                {
                  "op": "add",
                  "args": [
                    {"param": "one_constant"},
                    {
                      "op": "negate",
                      "args": [
                        {
                          "op": "divide",
