                            {"param": "T_H_heisenberg_time"}
                          ]
                        }
                      ]
                    },
                    {
                      "op": "divide",
                      "args": [
                        {
                          "op": "power",
                          "args": [
                            {"var": "time_t"},
                            {"param": "two_constant"}
                          ]
                        },
                        {
                          "op": "multiply",
                          "args": [
                            {"param": "three_constant"},
                            {
                              "op": "power",
                              "args": [
                                {"param": "T_H_heisenberg_time"},
                                {"param": "two_constant"}
                              ]
                            }
                          ]
                        }
                      ]
                    }
                  ]
                }
              ]
            },
            {"param": "undetermined_constant"}
          ]
        }
      },
      "mechanism_ids": ["pole_structure_mechanism", "sine_kernel_mechanism"],
      "control_names": ["time_t"],
      "control_domains": [
        {
          "control_name": "time_t",
          "domain_kind": "continuous_interval",
          "minimum": 0.0,
          "maximum": null,
          "allowed_values": [],
          "domain_statement": "The formula is given for t < T_H and t >= T_H; t is non-negative.",
          "anchors": [
