              "support": "C(t) is given for t < T_H and t >= T_H."
            }
          ]
        }
      ],
      "readout_names": ["complexity_C"],
      "fixed_condition_ids": ["microcanonical_ensemble", "gue_universality", "alpha_T_H_large"],
      "applicability": "The formula applies to the GUE example with alpha T_H >> 1, in the microcanonical ensemble, and for t < T_H and t >= T_H. The additive constant is undetermined.",
      "statistical_basis": "Ensemble-averaged expectation value; derived from the generating function via regularization and alpha -> 0 limit.",
      "uncertainty": "source_unspecified",
      "depends_on": [],
      "anchors": [
